package com.wayrapass.controller; import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.CatalogResponses;import com.wayrapass.service.CatalogService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/institutions") @RequiredArgsConstructor public class InstitutionController{private final CatalogService s;@GetMapping public List<CatalogResponses.Institution> all(){return s.institutions();}@GetMapping("/{id}") public CatalogResponses.Institution one(@PathVariable Long id){return s.institution(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Institution create(@Valid @RequestBody CatalogRequests.Institution r){return s.saveInstitution(null,r);}@PutMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Institution update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Institution r){return s.saveInstitution(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('COORDINATOR')") public void delete(@PathVariable Long id){s.deleteInstitution(id);}}
